import {sideLengths} from './transport-price.mjs';
import {MATERIALS,MATERIAL_CATALOG_NOTE,materialPriceLine} from './rule-data.mjs';
const f=n=>new Intl.NumberFormat('da-DK',{maximumFractionDigits:2}).format(n);
const kr=n=>new Intl.NumberFormat('da-DK',{minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const input=(label,value,attrs,unit='kr.')=>`<label class="field"><span>${label}</span><span class="input-wrap"><input type="number" inputmode="decimal" min="0" step="0.01" value="${e(value)}" aria-label="${e(label)}" ${attrs}><span>${unit}</span></span></label>`;
const textInput=(label,value,attrs)=>`<label class="field"><span>${label}</span><input type="text" maxlength="240" value="${e(value)}" ${attrs}></label>`;
function materialControls(p,zones){
 const rows=p.materials||[];
 return `<div class="materials-editor"><p class="hint">${MATERIAL_CATALOG_NOTE} Grundpriser uden T og øvrige priser holdes automatisk uden for transportgrundlaget.</p>${rows.map((m,index)=>{
  const id=m.id??String(index),item=MATERIALS.find(i=>i.id===m.itemId),attr=field=>`data-material-field="${field}" data-material-id="${e(id)}"`;
  let preview='';
  try{const r=materialPriceLine({...m,operation:p.operation||'montage'});preview=`${f(r.billedQuantity)} × ${kr(r.rate)}${r.unit==='cm'?' / 100':''} = ${kr(r.workAmount)} kr. · T-grundlag ${kr(r.tBase)} kr.`;}catch{}
  return `<article class="material-card panel"><div class="panel-header"><h3>Materiale ${index+1}</h3><button class="link-button" data-action="remove-material" data-material-id="${e(id)}">Fjern</button></div><label class="field"><span>Prisrække</span><select ${attr('itemId')}><option value="">Manuel prisrække – angiv kilde og G/T/H</option>${MATERIALS.map(v=>`<option value="${e(v.id)}" ${v.id===m.itemId?'selected':''}>${e(v.id)} · ${e(v.label)} · ${kr(v.rate)} kr.${v.unit==='cm'?' pr. 100 cm':''} [${v.G?'G':''}${v.T?'T':''}${v.H?'H':''}]</option>`).join('')}</select></label><div class="field-grid">${input('Mængde',m.quantity??'',attr('quantity'),item?.unit==='piece'?'stk.':item?.unit==='room'?'rum':item?.unit==='sqm'?'m²':item?.unit||'enheder')}<label class="field"><span>Transportområde</span><select ${attr('zoneId')}><option value="">Vælg område</option>${zones.map((z,i)=>`<option value="${e(z.id)}" ${z.id===m.zoneId?'selected':''}>${i+1} · ${e(z.side)}${z.from!=null?` ${f(z.from)}–${f(z.to)} m`:''} · ${z.percent==null?'afklares':`${f(z.percent)} %`}</option>`).join('')}</select></label></div>${!item?`<div class="field-grid">${textInput('Materiale / arbejde',m.label||'',attr('label'))}${input('Pris pr. opgjort enhed',m.rate??'',attr('rate'))}${textInput('Prisrække og regelhenvisning',m.ref||'',attr('ref'))}${input('Faktor ved demontage',m.demontageFactor??(m.G?.5:1),attr('demontageFactor'),'×')}</div><div class="checks">${[['G','G · Grundpris'],['T','T · Transportberettiget'],['H','H · Højdeberettiget'],['mountOnly','Kun betaling ved montage']].map(([field,label])=>`<label class="check"><input type="checkbox" ${m[field]?'checked':''} ${attr(field)}><span>${label}</span></label>`).join('')}</div><p class="hint">Brug den opgjorte mængde efter prisrækkens enhedsregel. For ikke-prissatte arbejder bruges Særskilt aftale. T gives kun, når linjen også er G.</p>`:''}${item?.tentBasis?`<label class="check"><input type="checkbox" ${m.correctTentBasis?'checked':''} ${attr('correctTentBasis')}><span>Prisgrundlaget følger København / Nordsjælland 1. og 2. zone (A35)</span></label>`:''}${preview?`<p class="rule-ref">${e(preview)}</p>`:''}</article>`;
 }).join('')}<button class="btn secondary" data-action="add-material">Tilføj materiale +</button></div>`;
}
export function priceControls(p,zones,{guided=false}={}){
 const choices=['precise','zones'].includes(p.mode)
  ? [['precise','Materialer pr. område','Optæl med prisrækker fra HP3'],['zones','Grundpris pr. zone','Skriv de faktiske beløb i trin 3']]
  : [['uniform','Efter meter','Overslag med ens opbygning'],['sides','Pr. husside','Fordel i kroner eller procent']];
 const distribution=guided?`<div class="field transport-distribution"><span>Hvordan fordeles grundprisen?</span><div class="transport-distribution-options" role="group" aria-label="Prisfordeling">${choices.map(([mode,title,help])=>`<button class="tk-choice" data-price-mode-choice="${mode}" aria-pressed="${mode===p.mode}"><b>${title}</b><small>${help}</small></button>`).join('')}</div></div>`:null;
 const exact=['zones','precise'].includes(p.mode),isKr=p.shareUnit==='kr';
 return `<section class="panel montage-panel"><div class="montage-heading"><div><span class="eyebrow">TRIN 1 · PRISGRUNDLAG</span><h2>${exact?'Opgør dit prisgrundlag':'Hvad er din montagepris?'}</h2><p>Materialer × grundpriser før tillæg. Ved nedtagning indtastes stadig den fulde montagegrundpris.</p></div>${!exact?input('Fuld montagegrundpris før tillæg',p.montage,'data-price-field="montage"'):'<span class="micro-tag">PRÆCIS FORDELING</span>'}</div>
 <div class="montage-options"><label class="field"><span>Hvad udfører I?</span><select data-price-field="operation"><option value="montage" ${p.operation!=='demontage'?'selected':''}>Montage</option><option value="demontage" ${p.operation==='demontage'?'selected':''}>Demontage / nedtagning</option></select><small>${p.operation==='demontage'?'Arbejdsgrundpris normalt 50 %. Transport beregnes stadig af 100 % af det fulde T-grundlag (A8/A13/pkt. 27).':'Kun G er grundlag for procenttillæg. Der beregnes ingen procent af andre tillæg.'}</small></label>${distribution??`<label class="field"><span>Prisfordeling</span><select data-price-mode aria-label="Prisfordeling"><option value="uniform" ${p.mode==='uniform'?'selected':''}>Fordelt · automatisk efter meter</option><option value="sides" ${p.mode==='sides'?'selected':''}>Fordelt · justér sider i kr. eller %</option><option value="precise" ${p.mode==='precise'?'selected':''}>Præcis · materialer pr. område</option><option value="zones" ${p.mode==='zones'?'selected':''}>Præcis · faktiske T-grundpriser pr. zone</option></select></label>`}</div>
 ${p.mode!=='precise'?`<details class="montage-exclusions" ${Number(p.withoutT)>0||Number(p.extra)>0?'open':''}><summary>Grundpriser uden T og øvrige beløb</summary><div class="detail-content"><div class="field-grid">${input('Grundpriser uden T',p.withoutT??0,'data-price-field="withoutT"')}${input('Øvrige beløb, uden procenttillæg',p.extra??0,'data-price-field="extra"')}</div><p class="hint">${p.mode==='zones'?'Grundpriser uden T lægges til zonegrundpriserne.':'Grundpriser uden T er allerede indeholdt i montageprisen og trækkes fra T-grundlaget.'} Øvrige beløb lægges til totalen med det indtastede beløb. Ved særlige demontageregler bruges materialevis opgørelse.</p></div></details>`:`<div class="field-grid">${input('Øvrige aftalte beløb, uden procenttillæg',p.extra??0,'data-price-field="extra"')}</div>`}
 ${p.mode==='sides'?`<label class="field"><span>Angiv siderne i</span><select data-price-field="shareUnit"><option value="percent" ${!isKr?'selected':''}>Procent af T-grundlaget</option><option value="kr" ${isKr?'selected':''}>Kroner af T-grundlaget</option></select></label><div class="side-share-grid">${sideLengths(zones).map(s=>`<div>${input(`${s.side} · ${isKr?'grundpris':'andel af prisen'}`,p.shares?.[s.side]??'',`data-price-share="${e(s.side)}" ${!isKr?'max="100"':''}`,isKr?'kr.':'%')}<small>${f(s.length)} m · <span data-side-price="${e(s.side)}">—</span> kr.</small></div>`).join('')}</div><p class="price-assumption">${isKr?'Fordel hele T-grundlaget i kroner.':'Fordel 100 % i alt.'} Der forudsættes ens grundpris pr. meter inden for hver side. Mere grej på én del af siden kræver Præcis.</p>`:p.mode==='uniform'?'<p class="price-assumption"><b>Overslag efter meter.</b> Forudsætter samme montagegrundpris pr. meter: samme højde, dæk og opbygning. Har bagsiden mere grej, justér prisfordelingen.</p>':p.mode==='precise'?materialControls(p,zones):'<p class="hint">Indtast de fulde T-grundpriser under Rute (trin 3). Skriv 0 i områder uden transportberettiget materiel.</p>'}
 </section>`;
}
export function priceSummary(v,agreed,{excluded=false,saveAction='save-house',saveLabel='Føj transporttillæg til mit ark ↗',allowProvisional=false,confirmation=''}={}){
 if(!v.complete)return `<div class="price-empty"><b>${e(v.reason||'Skriv din montagepris ovenfor.')}</b>${v.previewPercent!=null?`<p>Vejledende pkt. 27-beregning: ${f(v.previewPercent)} %${v.previewAmount!=null?` = ${kr(v.previewAmount)} kr.`:''} Kræver afklaring; dette er ikke et afklaret krav.</p>`:'<p>Hver transportvej vægtes efter de grundpriser, der hører til den.</p>'}</div>`;
 const distribution=v.mode==='quick'?'Én pris og én transportvej.':v.mode==='uniform'?'Overslag efter meter · ens grundpris pr. meter.':v.mode==='sides'?'Fordelt efter dine sideandele · ens grundpris pr. meter inden for hver side.':v.mode==='precise'?'Vægtet efter de opgjorte materialer og deres G/T/H-markering.':'Vægtet efter dine faktiske zonebeløb.';
 const saveable=agreed&&(!v.provisional||allowProvisional);
 return `${v.provisional?'<div class="note-card warning"><div><b>Vejledende beregning – kræver afklaring.</b> Det viste transportforhold kræver afklaring. En konkret aftale skal dokumenteres, før beløbet bruges som krav.</div></div>':''}${v.warnings?.length?`<div class="note-card neutral"><div>${v.warnings.map(e).join('<br>')}</div></div>`:''}<div class="montage-result"><div><span>${v.provisional?'VEJLEDENDE TRANSPORTPROCENT':'SAMLET TRANSPORTPROCENT'}</span><strong>${f(v.percent)} <small>%</small></strong><p>${distribution}</p></div><div><span>TRANSPORTTILLÆG</span><strong>${kr(v.amount)} <small>kr.</small></strong><p>Af ${kr(v.base)} kr. fuldt T-grundlag${v.operation==='demontage'?' · ikke halveret':''}</p></div></div>
 ${!excluded&&v.base>0?`<div class="seven-comparison"><span>Ved kun 7 %: <b>${kr(v.sevenAmount)} kr.</b></span><strong>${v.difference>=0?'+':'−'}${kr(Math.abs(v.difference))} kr.</strong><small>${v.difference>0?'Forskel for de længere transportveje':v.difference===0?'Samme tillæg som 7 %':'Forskel fra en fast sats på 7 %'}</small></div>`:''}
 <div class="montage-equation"><span>${v.operation==='demontage'?'Nedtagningsgrundpris':'Montagegrundpris'}</span><b>${kr(v.workBase??v.montage)} kr.</b>${v.extras?`<span>+ øvrige beløb</span><b>${kr(v.extras)} kr.</b>`:''}<span>+ transporttillæg</span><b>${kr(v.amount)} kr.</b><span>= ${v.operation==='demontage'?'nedtagning':'montage'} inkl. transport</span><strong>${kr(v.workWithTransport??v.montageWithTransport)} kr.</strong></div>
 ${v.operation==='demontage'?`<p class="hint"><b>Fuld montagegrundpris ${kr(v.montage)} kr.</b> Arbejdsgrundprisen er normalt halveret; transportgrundlaget er det fulde T-berettigede G. Særregler for bestemte poster håndteres i Præcis.</p>`:''}<p class="hint">Procenten vises med to decimaler. Kroner beregnes af de fulde delbeløb før visningens afrunding. Der beregnes aldrig procent af tidligere tillæg. ${['uniform','sides'].includes(v.mode)?'Fordelingen er en forudsætning, ikke en materialeoptælling.':''}</p>
 ${confirmation?`<div class="transport-confirmation">${confirmation}</div>`:''}<div class="table-footer"><p class="hint">${v.provisional&&!allowProvisional?'Afklar transportforholdet eller indtast den særskilte aftale før et krav gemmes.':agreed?'Ruter og transportmiddel er markeret afklaret.':'Markér afklaringen af ruter og transportmiddel, før du gemmer.'}</p><button class="btn" data-action="${e(saveAction)}" ${saveable?'':'disabled'}>${e(saveLabel)}</button></div>`;
}
export function priceBreakdown(v){
 if(!v.complete)return '';
 return `<div class="price-breakdown"><h3>Sådan er transporttillægget beregnet</h3><p>Hver T-berettiget grundpris får satsen for sin transportvej. Delbeløbene lægges sammen.</p><table><thead><tr><th>Transport</th><th>Fuldt T-grundlag</th><th>Tillæg</th></tr></thead><tbody>${v.groups.map(g=>`<tr><td><b>${f(g.percent)} %</b></td><td>${kr(g.base)} kr.</td><td>${kr(g.amount)} kr.</td></tr>`).join('')}${v.rounding?`<tr><td colspan="2">Forskel fra linjernes viste øreafrunding</td><td>${kr(v.rounding)} kr.</td></tr>`:''}</tbody></table>${v.materialRows?.length?`<details class="details-control"><summary>Se materialernes G/T/H og mellemregninger</summary><div class="detail-content">${v.materialRows.map(m=>`<p><b>${e(m.id||m.itemId||'Manuel prisrække')} · ${e(m.label)}</b><br>${e(m.formula)} = ${kr(m.workAmount)} kr. · ${m.G?'G':''}${m.T?'T':''}${m.H?'H':''}<br>Transportgrundlag: ${kr(m.tBase)} kr. · ${e(m.zoneName)}<br><span class="rule-ref">${e(m.ref)}</span></p>`).join('')}</div></details>`:''}<p class="rule-ref">A8 · A13 · pkt. 27 · Opbygning s. 13. Transport af fulde T-grundpriser, også ved demontage.</p></div>`;
}
